{
  "name": "@cognitionai/opencode-devin",
  "version": "0.3.0",
  "description": "OpenCode plugin: log in with Devin and use Devin's AI Gateway",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/CognitionAI/opencode-devin.git"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "devin"
  ],
  "scripts": {
    "build": "rm -rf dist && tsc -p tsconfig.build.json",
    "typecheck": "tsc --noEmit",
    "lint": "prettier --check .",
    "format": "prettier --write .",
    "test": "bun test",
    "release": "bash scripts/publish.sh"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.14"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.25",
    "@types/bun": "1.4.0",
    "prettier": "3.6.2",
    "typescript": "6.0.3"
  }
}
